export const TEMPLATE_03_BUNDLED_HTML = "<!DOCTYPE html>\r\n<html lang=\"en\">\r\n<head>\n<style>\n@font-face {\n  font-family: 'Great Vibes';\n  src: url('data:font/ttf;base64,') format('truetype');\n  font-weight: 400;\n  font-style: normal;\n}\n@font-face {\n  font-family: 'Cormorant Garamond';\n  src: url('data:font/ttf;base64,') format('truetype');\n  font-weight: 400 500;\n  font-style: normal;\n}\n@font-face {\n  font-family: 'Cormorant Garamond';\n  src: url('data:font/ttf;base64,') format('truetype');\n  font-weight: 600 700;\n  font-style: normal;\n}\n@font-face {\n  font-family: 'Baloo 2';\n  src: url('data:font/ttf;base64,') format('truetype');\n  font-weight: 500 700;\n  font-style: normal;\n}\n@font-face {\n  font-family: 'Cinzel Decorative';\n  src: url('data:font/ttf;base64,') format('truetype');\n  font-weight: 700;\n  font-style: normal;\n}\n@font-face {\n  font-family: 'Playfair Display';\n  src: url('data:font/ttf;base64,') format('truetype');\n  font-weight: 400 700;\n  font-style: normal;\n}\n</style>\n\n<script>\n(function() {\n  function postToNative(type, payload) {\n    if (window.ReactNativeWebView && typeof window.ReactNativeWebView.postMessage === 'function') {\n      window.ReactNativeWebView.postMessage(JSON.stringify({ type: type, payload: payload }));\n    }\n  }\n  window.__POST_TO_NATIVE__ = postToNative;\n\n  window.addEventListener('DOMContentLoaded', function() {\n    postToNative('TEMPLATE_READY', { templateId: 'tpl-wedding-temple-03', ready: true });\n  });\n\n  window.addEventListener('message', function(e) {\n    if (e.data && e.data.type === 'INK_IVORY_CUSTOM_UPDATE') {\n      postToNative('INVITATION_UPDATED', { success: true, timestamp: Date.now() });\n    }\n  });\n\n  window.addEventListener('error', function(err) {\n    postToNative('RENDER_ERROR', { message: err.message, filename: err.filename, lineno: err.lineno });\n  });\n})();\n</script>\n\r\n<meta charset=\"utf-8\">\r\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1, viewport-fit=cover\">\r\n<title>Thirumanam — Karthik &amp; Meenakshi — South Indian Temple Wedding Invitation</title>\r\n\r\n\r\n\r\n<style>\r\n:root{\r\n  --crimson:#6a0d20; --crimson-d:#38050e; --crimson-darker:#1a0206;\r\n  --wine:#0d382c; --night:#062018;\r\n  --cream:#fbf5e6; --cream2:#f2e5c6; --paper:#fffaf0;\r\n  --gold:#d9a521; --gold2:#f7de8a; --brass:#a87819; --vermilion:#c92a3e; --ink:#1f2a1c;\r\n  --serif:'Cormorant Garamond',Georgia,serif;\r\n  --display:'Playfair Display',Georgia,serif;\r\n  --sans:'Karla',system-ui,-apple-system,sans-serif;\r\n  --tamil:'Noto Serif Tamil',var(--serif);\r\n  --bar-h:34px;\r\n}\r\n*{box-sizing:border-box;margin:0;padding:0}\r\nhtml{scroll-behavior:smooth;scroll-padding-top:var(--bar-h);scrollbar-width:none!important;-ms-overflow-style:none!important}\r\nhtml::-webkit-scrollbar,body::-webkit-scrollbar,::-webkit-scrollbar{display:none!important;width:0px!important;height:0px!important;background:transparent!important}\r\nbody{font-family:var(--sans);background:radial-gradient(ellipse at center,#142820,#061510);color:var(--ink);overflow-x:hidden;-webkit-font-smoothing:antialiased;scrollbar-width:none!important;-ms-overflow-style:none!important}\r\nbody.lock{overflow:hidden}\r\n#app{max-width:520px;margin:0 auto;background:var(--cream);min-height:100vh;box-shadow:0 0 60px rgba(0,0,0,0.65);position:relative;overflow-x:hidden}\r\nh1,h2,h3{font-family:var(--serif);font-weight:600;line-height:1.1}\r\nsection{padding:clamp(60px,9vw,110px) 20px;text-align:center;position:relative}\r\nh2{font-size:clamp(2.1rem,5vw,3.3rem)}\r\n.kick{font-size:.78rem;letter-spacing:.28em;color:var(--brass);margin-bottom:12px;font-weight:700;text-transform:uppercase}\r\n.sub{font-family:var(--serif);font-style:italic;font-size:1.25rem;opacity:.85;margin:10px auto 34px;max-width:580px;line-height:1.5}\r\n.dots{display:flex;align-items:center;justify-content:center;gap:10px;margin:14px auto;color:var(--gold)}\r\n.dots:before,.dots:after{content:\"\";width:60px;height:1px;background:currentColor}\r\n.dots i{width:7px;height:7px;background:currentColor;transform:rotate(45deg)}\r\n:focus-visible{outline:3px solid var(--gold);outline-offset:3px}\r\n.btn{display:inline-flex;align-items:center;gap:8px;background:linear-gradient(#f7de8a,#d9a521,#a87819);color:#240409;border:0;border-radius:999px;padding:14px 32px;font:700 1rem var(--sans);cursor:pointer;box-shadow:0 8px 20px rgba(0,0,0,0.35);text-decoration:none;transition:transform .2s,filter .2s,box-shadow .2s}\r\n.btn:hover{transform:translateY(-2px);filter:brightness(1.08);box-shadow:0 10px 26px rgba(0,0,0,0.45)}\r\n.btn.ghost{background:transparent;color:inherit;border:1.5px solid currentColor;box-shadow:none}\r\n.night{background:radial-gradient(ellipse at 50% 0,#124a38,var(--night) 70%);color:var(--cream)}\r\n.pat:before{content:\"\";position:absolute;inset:0;background-image:radial-gradient(#d9a52126 1.4px,transparent 1.5px);background-size:26px 26px;pointer-events:none}\r\n.pat>*{position:relative;z-index:1}\r\n@keyframes spin{to{transform:rotate(360deg)}}\r\n.rev{opacity:0;transform:translateY(22px);transition:opacity .9s ease,transform .9s cubic-bezier(.2,.8,.2,1)}.rev.in{opacity:1;transform:none}\r\n\r\n/* ---------- PREVIEW BAR ---------- */\r\n#bar{position:fixed;top:0;left:0;right:0;height:var(--bar-h);z-index:130;display:flex;align-items:center;gap:6px;padding:0 14px;\r\n  background:linear-gradient(#2d2842,#2d2842e6);backdrop-filter:blur(8px);font-family:var(--sans);font-size:11px;font-weight:600;color:#e9e6f3;\r\n  transform:translateY(-100%);transition:transform .7s .2s cubic-bezier(.2,.8,.2,1)}\r\nbody.ready #bar{transform:none}\r\nbody.nobar #bar{display:none}\r\n#bar .nav{display:flex;align-items:center;gap:4px;padding:6px 8px;border-radius:6px;background:none;border:none;color:inherit;cursor:pointer}\r\n#bar .nav:hover{background:#ffffff14}\r\n#bar .sp{flex:1}\r\n#choose{background:linear-gradient(#f7de8a,#d9a521);color:#240409;font-weight:700;padding:6px 14px;border-radius:7px;font-size:11px;box-shadow:0 2px 8px #0005;text-decoration:none;display:inline-flex;align-items:center}\r\n#toast{position:fixed;top:48px;left:50%;transform:translate(-50%,-20px);background:#1c1832;color:#fff;font-family:var(--sans);font-size:12px;padding:10px 18px;border-radius:999px;z-index:140;opacity:0;pointer-events:none;transition:all .4s;box-shadow:0 4px 16px rgba(0,0,0,0.4)}\r\n#toast.show{opacity:1;transform:translate(-50%,0)}\r\n\r\n/* ---------- LOADER : AURA & TAMIL BLESSING ---------- */\r\n#loader{position:fixed;inset:0;z-index:120;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:14px;background:radial-gradient(circle at 50% 40%,#590919,#062018 82%);color:var(--gold2);transition:opacity .9s,visibility .9s}\r\n#loader.hide{opacity:0;visibility:hidden;pointer-events:none}\r\n#lm{width:min(62vw,240px);height:auto;overflow:visible;animation:spin 28s linear infinite}\r\n#lm *{fill:none;stroke:#d9a521;stroke-width:.8;stroke-dasharray:1;stroke-dashoffset:1;animation:draw 1.6s ease forwards;animation-delay:var(--d)}\r\n@keyframes draw{to{stroke-dashoffset:0}}\r\n#loader .lname{font:600 2.2rem var(--serif);letter-spacing:.06em;color:var(--cream);margin-top:10px}\r\n#loader p{font:italic 1.15rem var(--serif);opacity:.9;text-align:center;line-height:1.5}\r\n.lbar{width:190px;height:3px;background:#ffffff22;border-radius:3px;overflow:hidden}\r\n.lbar i{display:block;height:100%;background:linear-gradient(90deg,var(--gold),var(--gold2));transform-origin:left;transform:scaleX(0);animation:fillbar 2.6s ease forwards}\r\n@keyframes fillbar{to{transform:scaleX(1)}}\r\n\r\n/* ========================================================================= */\r\n/* ---------- GATE : ROYAL TEMPLE CARVED DOORS & SANCTUM REVEAL ---------- */\r\n/* ========================================================================= */\r\n#gate{position:fixed;inset:0;z-index:100;background:radial-gradient(ellipse at center,#240409,#090103);display:flex;align-items:center;justify-content:center;overflow:hidden;user-select:none}\r\n.gate-wrap{position:relative;width:min(100vw,520px);height:100%;overflow:hidden;box-shadow:0 0 80px rgba(0,0,0,0.9),0 0 30px rgba(217,165,33,0.25)}\r\n\r\n#gate .reveal{position:absolute;inset:0;display:flex;align-items:center;justify-content:center;text-align:center;padding:24px;\r\n  background:radial-gradient(ellipse at center,rgba(255,250,240,0.95),rgba(245,230,200,0.96)),url('/template-03/couple.jpg');\r\n  background-size:cover;background-position:center;z-index:1}\r\n.reveal-card{max-width:440px;width:90%;padding:36px 24px;background:rgba(255,250,240,0.94);border-radius:200px 200px 24px 24px;border:2px solid var(--gold);box-shadow:0 0 0 6px #fffaf0,0 0 0 8px var(--gold),0 24px 60px rgba(10,58,44,0.3);animation:revealCardZoom 1.4s ease forwards}\r\n@keyframes revealCardZoom{from{opacity:0;transform:scale(0.92) translateY(15px)}to{opacity:1;transform:scale(1) translateY(0)}}\r\n.reveal-kicker{font-family:var(--tamil);font-size:13px;font-weight:700;color:var(--vermilion);letter-spacing:.08em;margin-bottom:8px}\r\n.reveal-title{font-family:var(--serif);font-size:clamp(2.5rem,7vw,3.8rem);font-weight:700;color:var(--crimson);line-height:1.1}\r\n.reveal-names{font-family:var(--serif);font-size:clamp(1.8rem,5vw,2.6rem);font-weight:600;color:var(--wine);margin:12px 0 6px}\r\n.reveal-desc{font-family:var(--serif);font-style:italic;font-size:1.15rem;color:#5a4030;line-height:1.5}\r\n\r\n/* The Grand Symmetrical Double Temple Doors */\r\n.door{position:absolute;top:0;bottom:0;width:50.2%;background-image:url('/template-03/entrance-doors.jpg');background-size:200% 100%;background-repeat:no-repeat;transition:transform 1.9s cubic-bezier(.75,0,.2,1),opacity .6s 1.4s;z-index:3;overflow:hidden;box-shadow:0 0 35px rgba(0,0,0,0.85)}\r\n.door.dl{left:0;background-position:left center}\r\n.door.dr{right:0;background-position:right center}\r\n\r\n/* 24K Gold Seam down the center */\r\n.door::after{content:\"\";position:absolute;top:0;bottom:0;width:3.5px;\r\n  background:linear-gradient(transparent,#ffe8aa 12%,#d9a521 50%,#ffe8aa 88%,transparent);\r\n  box-shadow:0 0 14px rgba(247,222,138,0.8);opacity:.95;z-index:2}\r\n.door.dl::after{right:0}\r\n.door.dr::after{left:0}\r\n\r\n/* Open doors animation */\r\n#gate.open .dl{transform:translateX(-101%);opacity:0}\r\n#gate.open .dr{transform:translateX(101%);opacity:0}\r\n\r\n/* Door architectural relief overlay */\r\n.door-art{position:absolute;inset:0;width:100%;height:100%;pointer-events:none}\r\n\r\n/* Floating Flower Petals Canvas on Gate */\r\n#gateCv{position:absolute;inset:0;z-index:2;pointer-events:none}\r\n\r\n/* ---------- CENTERPIECE : SACRED MANDALA & TEMPLE SEAL ---------- */\r\n.seal{position:absolute;z-index:4;left:50%;top:50%;transform:translate(-50%,-50%);text-align:center;color:var(--cream);transition:opacity .6s ease;width:min(90vw,440px)}\r\n#gate.open .seal{opacity:0;pointer-events:none}\r\n#gate.gone{display:none}\r\n\r\n/* Glowing Divine Aura */\r\n.seal-halo{position:absolute;left:50%;top:38%;transform:translate(-50%,-50%);width:min(78vmin,380px);height:min(78vmin,380px);border-radius:50%;\r\n  background:radial-gradient(circle,#f7de8a45,#d9a52120 48%,transparent 72%);pointer-events:none;animation:haloBreathe 4s ease-in-out infinite alternate}\r\n@keyframes haloBreathe{0%{transform:translate(-50%,-50%) scale(.92);opacity:.75}100%{transform:translate(-50%,-50%) scale(1.08);opacity:1}}\r\n\r\n/* Concentric Animated Kolam / Lotus Rangoli */\r\n.seal-kolam{position:relative;width:clamp(160px,26vmin,220px);aspect-ratio:1;margin:0 auto 16px;filter:drop-shadow(0 8px 24px rgba(0,0,0,0.65))}\r\n.seal-kolam svg{width:100%;height:100%;overflow:visible}\r\n.spin-slow{transform-box:view-box;transform-origin:100px 100px;animation:spin 90s linear infinite}\r\n.spin-rev{transform-box:view-box;transform-origin:100px 100px;animation:spin 120s linear infinite reverse}\r\n\r\n/* 24K Gold Medallion */\r\n.seal-medallion{position:absolute;left:50%;top:50%;transform:translate(-50%,-50%);\r\n  width:clamp(86px,14vmin,112px);height:clamp(86px,14vmin,112px);border-radius:50%;\r\n  background:radial-gradient(circle at 35% 30%,#a8203d,#4a0715 70%);\r\n  border:3px solid #f7de8a;\r\n  box-shadow:0 0 0 4px #d9a52188,0 0 24px rgba(247,222,138,0.6),inset 0 0 16px rgba(0,0,0,0.7);\r\n  display:flex;flex-direction:column;align-items:center;justify-content:center;\r\n  color:#fffaf0;cursor:pointer;transition:transform .3s ease}\r\n.seal-medallion:hover{transform:translate(-50%,-50%) scale(1.06)}\r\n.seal-medallion .initials{font-family:'Cinzel Decorative',var(--serif);font-size:clamp(22px,3.8vmin,30px);font-weight:700;letter-spacing:1px;\r\n  background:linear-gradient(135deg,#fff,#f7de8a,#d9a521);-webkit-background-clip:text;-webkit-text-fill-color:transparent;\r\n  filter:drop-shadow(0 2px 4px rgba(0,0,0,0.6))}\r\n.seal-medallion .mini-ta{font-family:'Noto Serif Tamil',var(--serif);font-size:10px;color:#f7de8a;letter-spacing:.05em;margin-top:2px}\r\n\r\n/* Invitation presentation card below medallion */\r\n.seal-card{background:linear-gradient(135deg,rgba(38,5,12,0.92),rgba(18,2,5,0.96));backdrop-filter:blur(12px);border:1.5px solid rgba(247,222,138,0.65);border-radius:20px;\r\n  padding:22px 22px 24px;box-shadow:0 16px 44px rgba(0,0,0,0.75),inset 0 0 20px rgba(217,165,33,0.22)}\r\n.seal-card .eyebrow-seal{font-size:.74rem;letter-spacing:.28em;color:var(--gold2);font-weight:700;text-transform:uppercase;margin-bottom:8px}\r\n.seal-card .names-seal{font-family:var(--serif);font-size:clamp(1.9rem,5vw,2.7rem);font-weight:600;line-height:1.1;color:#fffaf0;margin:4px 0 8px;\r\n  text-shadow:0 2px 10px rgba(0,0,0,0.7)}\r\n.seal-card .names-seal span{color:var(--gold2);font-style:italic;margin:0 4px}\r\n.seal-card .sub-seal{font-family:var(--serif);font-style:italic;font-size:1.1rem;color:#f2e5c6;opacity:.92;line-height:1.4;margin-bottom:18px}\r\n\r\n/* Luxury Shimmering Gold Button */\r\n.btn-enter{display:flex;align-items:center;justify-content:center;gap:10px;width:100%;padding:15px 24px;border-radius:12px;\r\n  background:linear-gradient(135deg,#fae6a2 0%,#d9a521 50%,#a87819 100%);\r\n  color:#240409;font:700 1.05rem var(--sans);cursor:pointer;text-decoration:none;\r\n  box-shadow:0 8px 24px rgba(0,0,0,0.5),0 0 20px rgba(217,165,33,0.35);\r\n  border:1px solid #ffe8aa;position:relative;overflow:hidden;transition:transform .2s,filter .2s}\r\n.btn-enter:hover{transform:translateY(-2px);filter:brightness(1.08)}\r\n.btn-enter::after{content:\"\";position:absolute;top:0;left:-70%;width:45%;height:100%;\r\n  background:linear-gradient(90deg,transparent,rgba(255,255,255,0.7),transparent);\r\n  transform:skewX(-24deg);animation:btnShine 3.2s infinite}\r\n@keyframes btnShine{0%,60%{left:-70%}100%{left:140%}}\r\n\r\n#gate .skip{position:absolute;z-index:5;top:16px;right:16px;background:rgba(26,2,6,0.65);color:#fffaf0;\r\n  border:1px solid rgba(247,222,138,0.35);border-radius:999px;padding:8px 16px;font:600 .82rem var(--sans);\r\n  cursor:pointer;backdrop-filter:blur(6px);transition:background .2s,border-color .2s}\r\n#gate .skip:hover{background:rgba(26,2,6,0.9);border-color:#f7de8a}\r\n\r\n.ta{font-family:'Noto Serif Tamil',var(--serif);font-weight:500}\r\n\r\n/* ---------- HERO : SACRED THORANAM & ROYAL COUPLE PORTRAIT ---------- */\r\n#hero{min-height:100vh;display:flex;flex-direction:column;align-items:center;justify-content:center;padding:110px 18px 60px;background:linear-gradient(#fbf3e3,var(--cream2));position:relative}\r\n#garland{position:absolute;top:0;left:0;width:100%;height:190px;pointer-events:none;z-index:2}\r\n.hero-grid{display:flex;flex-direction:column;align-items:center;gap:26px;width:100%;max-width:460px;position:relative;z-index:3}\r\n\r\n/* Royal Couple in Ornate Brass Temple Prabhavali Arch */\r\n.couple-arch-container{display:flex;flex-direction:column;align-items:center;width:100%}\r\n.prabhavali-arch{position:relative;width:clamp(220px,60vw,280px);aspect-ratio:3/4.1;border-radius:140px 140px 18px 18px;padding:6px;\r\n  background:linear-gradient(135deg,#f7de8a,#d9a521 50%,#8a5a0c);\r\n  box-shadow:0 0 0 4px #590919,0 0 0 6px #d9a52166,0 20px 48px rgba(10,58,44,0.35);overflow:hidden}\r\n.couple-photo{width:100%;height:100%;object-fit:cover;object-position:center 22%;border-radius:134px 134px 12px 12px;display:block}\r\n.arch-border-glow{position:absolute;inset:0;border-radius:inherit;box-shadow:inset 0 0 24px rgba(217,165,33,0.35);pointer-events:none}\r\n.arch-crest{position:absolute;top:6px;left:50%;transform:translateX(-50%);width:30px;height:30px;border-radius:50%;background:radial-gradient(circle,#f7de8a,#d9a521);border:1.5px solid #fff;display:grid;place-items:center;box-shadow:0 2px 8px rgba(0,0,0,0.4);font-size:15px}\r\n.couple-badge{margin-top:14px;padding:7px 22px;border-radius:999px;background:rgba(255,250,240,0.95);border:1.5px solid var(--gold);box-shadow:0 4px 16px rgba(0,0,0,0.12);display:flex;align-items:center;gap:8px;font-family:var(--serif);font-weight:700;font-size:1.15rem;color:var(--crimson)}\r\n.couple-badge .badge-sep{color:var(--gold);font-size:.95rem}\r\n\r\n.namecard{width:100%;max-width:440px;padding:40px 24px 30px;background:#fffaf0;border-radius:190px 190px 22px 22px;\r\n  border:2px solid var(--gold);box-shadow:inset 0 0 0 7px #fffaf0,inset 0 0 0 8px var(--gold),0 20px 48px rgba(10,58,44,0.2);text-align:center}\r\n.namecard .tiny{font-size:.72rem;letter-spacing:.25em;color:var(--crimson);margin-bottom:10px;font-weight:700}\r\n.namecard h1{font-size:clamp(2.8rem,7.5vw,4.2rem);color:var(--wine)}\r\n.namecard .amp{display:block;font:italic 400 1.9rem var(--serif);color:var(--vermilion);margin:4px 0}\r\n.namecard p{margin:14px 0 0;color:#6a4a3c;line-height:1.6}\r\n.pill{display:inline-block;margin-top:18px;padding:9px 22px;border-top:1px solid var(--gold);border-bottom:1px solid var(--gold);font-family:var(--serif);font-size:1.2rem;color:var(--wine);font-weight:600}\r\n.hero-venue{font-family:var(--serif);font-style:italic;font-size:1.12rem;color:#6a4a3c;margin-top:14px;line-height:1.4}\r\n\r\n/* ---------- SAVE THE DATE ---------- */\r\n#save{background:linear-gradient(#0d4a38,#06241c)}\r\n#save h2{color:var(--cream)}\r\n.cal{width:min(92%,340px);margin:0 auto 24px;background:var(--cream);color:var(--ink);border-radius:16px;padding:20px 18px 14px;box-shadow:0 18px 40px #0007;position:relative}\r\n.cal:before{content:\"\";position:absolute;top:-8px;left:50%;transform:translateX(-50%);width:70%;height:10px;background:repeating-linear-gradient(90deg,var(--gold) 0 8px,transparent 8px 18px);border-radius:6px}\r\n.cal h3{font-size:1.4rem;margin-bottom:12px;color:var(--wine)}\r\n.cal .g{display:grid;grid-template-columns:repeat(7,1fr);gap:6px 0;font-size:.85rem}\r\n.cal .g span{height:30px;display:grid;place-items:center;border-radius:50%}\r\n.cal .hd{font-size:.68rem;color:#9a7a60;font-weight:700}\r\n.cal .on{background:var(--vermilion);color:#fff;font-weight:700;box-shadow:0 0 0 3px var(--gold);animation:glow 2s infinite}\r\n@keyframes glow{50%{box-shadow:0 0 0 6px #d9a52188}}\r\n.cal .ft{margin-top:12px;font-size:.78rem;color:#7a5a48;font-weight:600}\r\n#save .loc{font-family:var(--serif);font-size:1.4rem;color:var(--gold2);line-height:1.4}\r\n\r\n/* ---------- COUNTDOWN ---------- */\r\n#count h2{color:var(--cream)}\r\n.cd{display:flex;gap:16px;justify-content:center;flex-wrap:wrap;margin-top:12px}\r\n.tile{width:96px;padding:26px 0 14px;background:linear-gradient(var(--cream),var(--cream2));color:var(--wine);border-radius:48px 48px 12px 12px;border:3px solid var(--gold);box-shadow:inset 0 0 0 3px var(--cream),inset 0 0 0 4px var(--crimson),0 10px 24px #0008}\r\n.tile b{font:700 2.5rem var(--serif);display:block;line-height:1;font-variant-numeric:lining-nums;font-feature-settings:'lnum' 1}.tile small{font-size:.72rem;letter-spacing:.12em;color:var(--brass);font-weight:700}\r\n\r\n/* ---------- EVENTS ---------- */\r\n#events{background:linear-gradient(var(--cream2),#f8efd6)}\r\n#events h2{color:var(--wine)}\r\n.tl{max-width:960px;margin:0 auto;position:relative}\r\n.tl:before{content:\"\";position:absolute;left:50%;top:0;bottom:0;width:2px;background:linear-gradient(var(--gold),var(--vermilion),var(--gold))}\r\n.row{display:grid;grid-template-columns:1fr 90px 1fr;align-items:center;margin-bottom:56px}\r\n.row .card{grid-column:1}.row .dt{grid-column:2}.row .when{grid-column:3;text-align:left}\r\n.row:nth-child(even) .card{grid-column:3}.row:nth-child(even) .when{grid-column:1;grid-row:1;text-align:right}\r\n.row:nth-child(even) .dt{grid-row:1}.row:nth-child(even) .card{grid-row:1}\r\n.dt{width:70px;height:70px;margin:auto;border-radius:50%;background:radial-gradient(var(--crimson),var(--wine));color:var(--gold2);border:3px solid var(--gold);display:grid;place-items:center;font:700 1.8rem var(--serif);position:relative;z-index:1;box-shadow:0 0 0 6px var(--cream2);font-variant-numeric:lining-nums}\r\n.when{font-family:var(--serif);font-size:1.5rem;color:var(--wine);padding:0 10px}.when small{display:block;font:italic 400 1.1rem var(--serif);color:var(--brass)}\r\n.card{position:relative;margin:34px 10px 0;padding:34px 22px 24px;background:#fffaf0;border:1.5px solid var(--gold);border-radius:14px;box-shadow:inset 0 0 0 5px #fffaf0,inset 0 0 0 6px #d9a52188,0 14px 30px #0a3a2c26;text-align:center}\r\n.card .bells{position:absolute;top:-34px;left:0;right:0;display:flex;justify-content:center;gap:16px}\r\n.card .bells svg{width:20px;height:34px;transform-origin:top;animation:sway 3s ease-in-out infinite}\r\n.card .bells svg:nth-child(2n){animation-delay:-1.4s}\r\n@keyframes sway{50%{transform:rotate(9deg)}}\r\n.card h3{font-size:2rem;color:var(--crimson)}\r\n.card p{margin:6px 0;color:#6a4a3c;font-size:.95rem;line-height:1.5}\r\n.card .acts{margin-top:14px;display:flex;gap:8px;justify-content:center}\r\n.card .acts a{font-size:.85rem;font-weight:600;color:var(--wine);border:1.5px solid var(--gold);border-radius:999px;padding:7px 16px;text-decoration:none;transition:background .2s}\r\n.card .acts a:hover{background:var(--gold2)}\r\n\r\n/* ---------- FAMILY ---------- */\r\n#family{background:linear-gradient(#06241c,var(--wine));color:var(--cream)}\r\n.bar{max-width:640px;margin:0 auto 20px;padding:22px 26px;background:var(--cream);color:var(--wine);border-radius:80px 80px 18px 18px/60px 60px 18px 18px;border:2px solid var(--gold);box-shadow:0 10px 26px #0006}\r\n.bar small{display:block;font-size:.7rem;letter-spacing:.22em;color:var(--brass);margin-bottom:6px;font-weight:700}\r\n.bar span{font-family:var(--serif);font-size:1.35rem;font-weight:600}\r\n.lights{position:absolute;left:0;right:0;bottom:0;height:46px;pointer-events:none}\r\n\r\n/* ---------- KUTHUVILAKKU TEMPLE LAMP ---------- */\r\n#bless h2{color:var(--cream)}\r\n#bless{overflow:hidden}\r\n#lantern{position:relative;display:block;width:230px;height:330px;margin:0 auto;cursor:pointer;background:none;border:0}\r\n#lantern svg{position:relative;z-index:1;width:100%;height:100%;overflow:visible;transition:filter 1s}\r\n#lantern.lit svg{filter:drop-shadow(0 0 24px #ffb347cc)}\r\n#lantern .halo{position:absolute;left:50%;top:42%;width:440px;height:440px;margin:-220px 0 0 -220px;border-radius:50%;background:radial-gradient(circle,#ffcf6b66,#ffcf6b00 65%);opacity:0;transition:opacity 1s;pointer-events:none}\r\n#lantern.lit .halo{opacity:1;animation:breathe 3s ease-in-out infinite}\r\n@keyframes breathe{50%{transform:scale(1.12)}}\r\n#lantern .flame{opacity:0;transform-box:fill-box;transform-origin:50% 100%;transition:opacity .6s}\r\n#lantern.lit .flame{opacity:1;animation:flick .2s infinite alternate}\r\n@keyframes flick{to{transform:scale(.92,1.08) rotate(1.5deg)}}\r\n.star{position:absolute;left:50%;top:38%;width:6px;height:6px;border-radius:50%;background:var(--gold2);box-shadow:0 0 8px var(--gold2);animation:burst 2.4s ease-out forwards}\r\n@keyframes burst{to{transform:translate(var(--x),var(--y));opacity:0}}\r\n#msg{min-height:1.6em;font-family:var(--serif);font-style:italic;font-size:1.25rem;color:var(--gold2);margin-top:14px}\r\n\r\nfooter{background:radial-gradient(ellipse at 50% 0,#0b2a20,#04140f 70%);border-top:3px solid var(--gold);color:#cdb892;padding:54px 20px 90px;text-align:center}\r\n.fm{width:80px;height:80px;margin:0 auto 14px;border-radius:50%;border:2px solid var(--gold);display:grid;place-items:center;font:600 1.6rem var(--serif);color:var(--gold2);box-shadow:0 0 0 6px #d9a52122}\r\n.fn{font:600 1.1rem var(--serif);letter-spacing:.18em;margin-bottom:18px}\r\nfooter p.big{font:italic 1.6rem var(--serif);color:var(--gold2);margin-bottom:20px}\r\n\r\n/* ---------- MUSIC CONTROLLER ---------- */\r\n#music{position:fixed;right:16px;bottom:16px;z-index:95;width:54px;height:54px;border-radius:50%;border:2px solid var(--gold);background:var(--crimson);display:grid;place-items:center;padding:0;cursor:pointer;box-shadow:0 6px 16px #0007;transition:transform .2s,box-shadow .2s}\r\n#music:hover{transform:scale(1.06)}\r\n#music.on{box-shadow:0 0 0 4px rgba(217,165,33,0.4),0 8px 20px rgba(0,0,0,0.6)}\r\n#music .w{display:none}#music.on .w{display:block}#music.on .x{display:none}\r\n\r\n@media(max-width:700px){\r\n  .tl:before{left:28px}.row{grid-template-columns:56px 1fr;margin-bottom:30px}\r\n  .dt{width:50px;height:50px;font-size:1.3rem;box-shadow:0 0 0 4px var(--cream2)}\r\n  .row .dt,.row:nth-child(even) .dt{grid-column:1;grid-row:1}\r\n  .row .when,.row:nth-child(even) .when{grid-column:2;grid-row:1;text-align:left;font-size:1.2rem}\r\n  .row .card,.row:nth-child(even) .card{grid-column:2;grid-row:2;margin-top:44px}\r\n  #bar .nav span{display:none}\r\n  .seal{width:94vw}\r\n}\r\n</style>\r\n</head>\r\n<body class=\"lock\">\r\n\r\n<!-- ================= PREVIEW BAR ================= -->\r\n<div id=\"bar\" role=\"navigation\" aria-label=\"Preview controls\">\r\n  <button class=\"nav\" id=\"bBack\"><svg width=\"12\" height=\"12\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.4\" stroke-linecap=\"round\"><path d=\"M19 12H5m6-6-6 6 6 6\"/></svg><span>Back</span></button>\r\n  <button class=\"nav\" id=\"bPrev\"><svg width=\"12\" height=\"12\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.4\" stroke-linecap=\"round\"><path d=\"m15 6-6 6 6 6\"/></svg><span>Previous</span></button>\r\n  <button class=\"nav\" id=\"bNext\"><span>Next</span><svg width=\"12\" height=\"12\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.4\" stroke-linecap=\"round\"><path d=\"m9 6 6 6-6 6\"/></svg></button>\r\n  <span class=\"sp\"></span>\r\n  <a href=\"/customize/tpl-engagement-garden-03\" id=\"choose\">Choose this design &rarr;</a>\r\n</div>\r\n<div id=\"toast\" role=\"status\"></div>\r\n\r\n<!-- ================= PRELOADER ================= -->\r\n<div id=\"loader\" role=\"status\">\r\n  <svg id=\"lm\" viewBox=\"-60 -60 120 120\" aria-hidden=\"true\"></svg>\r\n  <div class=\"lname\" id=\"lName\">Karthik &amp; Meenakshi</div>\r\n  <p><span class=\"ta\" style=\"color:var(--gold2);font-size:1.3rem\">வணக்கம்</span><br>Preparing your South Indian temple wedding invitation</p>\r\n  <div class=\"lbar\"><i></i></div>\r\n</div>\r\n\r\n<!-- ================= GRAND SOUTH INDIAN TEMPLE MANDAPAM DOORS ================= -->\r\n<div id=\"gate\" role=\"button\" tabindex=\"0\" aria-label=\"Open the invitation\">\r\n <div class=\"gate-wrap\">\r\n  <!-- Reveal Scene behind the doors -->\r\n  <div class=\"reveal\">\r\n    <div class=\"reveal-card\">\r\n      <div class=\"reveal-kicker\">✨ ஸ்ரீரஸ்து • சுபமஸ்து • கல்யாணம் ✨</div>\r\n      <div class=\"reveal-title\">Thirumanam</div>\r\n      <div class=\"dots\"><i></i></div>\r\n      <div class=\"reveal-names\" id=\"rNames\">Karthik &amp; Meenakshi</div>\r\n      <p class=\"reveal-desc\" id=\"gReveal\">Together with their families, cordially invite you to celebrate the sacred wedding celebration</p>\r\n    </div>\r\n  </div>\r\n\r\n  <!-- Left Grand Teak & 24K Gold Temple Door -->\r\n  <div class=\"door dl\"></div>\r\n\r\n  <!-- Right Grand Teak & 24K Gold Temple Door -->\r\n  <div class=\"door dr\"></div>\r\n\r\n  <!-- Drifting Jasmine & Marigold Petals Canvas -->\r\n  <canvas id=\"gateCv\"></canvas>\r\n\r\n  <!-- Centerpiece Sacred Temple Seal & Presentation Card -->\r\n  <div class=\"seal\">\r\n    <!-- Radiant Halo -->\r\n    <div class=\"seal-halo\"></div>\r\n\r\n    <!-- Concentric Rotating Gold Kolam Mandala -->\r\n    <div class=\"seal-kolam\" id=\"kolamWrap\" aria-hidden=\"true\">\r\n      <svg viewBox=\"0 0 200 200\">\r\n        <defs>\r\n          <linearGradient id=\"kgold\" x1=\"0\" y1=\"0\" x2=\"1\" y2=\"1\">\r\n            <stop offset=\"0%\" stop-color=\"#fff8db\"/><stop offset=\"50%\" stop-color=\"#d9a521\"/><stop offset=\"100%\" stop-color=\"#8a5a0c\"/>\r\n          </linearGradient>\r\n        </defs>\r\n        <!-- Outer ring of 24 Deepam Oil Lamps -->\r\n        <g class=\"spin-slow\">\r\n          <circle cx=\"100\" cy=\"100\" r=\"92\" fill=\"none\" stroke=\"url(#kgold)\" stroke-width=\".8\" stroke-dasharray=\"2,4\"/>\r\n          <circle cx=\"100\" cy=\"100\" r=\"86\" fill=\"none\" stroke=\"url(#kgold)\" stroke-width=\"1.2\"/>\r\n          <!-- 24 Small Golden Flames -->\r\n          <g fill=\"#f7de8a\">\r\n            <circle cx=\"100\" cy=\"11\" r=\"2.6\"/><circle cx=\"123\" cy=\"14\" r=\"2.2\"/><circle cx=\"145\" cy=\"23\" r=\"2.2\"/>\r\n            <circle cx=\"163\" cy=\"37\" r=\"2.2\"/><circle cx=\"177\" cy=\"55\" r=\"2.2\"/><circle cx=\"186\" cy=\"77\" r=\"2.2\"/>\r\n            <circle cx=\"189\" cy=\"100\" r=\"2.6\"/><circle cx=\"186\" cy=\"123\" r=\"2.2\"/><circle cx=\"177\" cy=\"145\" r=\"2.2\"/>\r\n            <circle cx=\"163\" cy=\"163\" r=\"2.2\"/><circle cx=\"145\" cy=\"177\" r=\"2.2\"/><circle cx=\"123\" cy=\"186\" r=\"2.2\"/>\r\n            <circle cx=\"100\" cy=\"189\" r=\"2.6\"/><circle cx=\"77\" cy=\"186\" r=\"2.2\"/><circle cx=\"55\" cy=\"177\" r=\"2.2\"/>\r\n            <circle cx=\"37\" cy=\"163\" r=\"2.2\"/><circle cx=\"23\" cy=\"145\" r=\"2.2\"/><circle cx=\"14\" cy=\"123\" r=\"2.2\"/>\r\n            <circle cx=\"11\" cy=\"100\" r=\"2.6\"/><circle cx=\"14\" cy=\"77\" r=\"2.2\"/><circle cx=\"23\" cy=\"55\" r=\"2.2\"/>\r\n            <circle cx=\"37\" cy=\"37\" r=\"2.2\"/><circle cx=\"55\" cy=\"23\" r=\"2.2\"/><circle cx=\"77\" cy=\"14\" r=\"2.2\"/>\r\n          </g>\r\n        </g>\r\n        <!-- Middle Counter-Rotating Sacred Padma Petals -->\r\n        <g class=\"spin-rev\">\r\n          <circle cx=\"100\" cy=\"100\" r=\"72\" fill=\"none\" stroke=\"url(#kgold)\" stroke-width=\".8\"/>\r\n          <path d=\"M100 28 C90 55, 90 75, 100 100 C110 75, 110 55, 100 28 Z\" fill=\"url(#kgold)\" opacity=\".3\"/>\r\n          <path d=\"M100 172 C90 145, 90 125, 100 100 C110 125, 110 145, 100 172 Z\" fill=\"url(#kgold)\" opacity=\".3\"/>\r\n          <path d=\"M28 100 C55 90, 75 90, 100 100 C75 110, 55 110, 28 100 Z\" fill=\"url(#kgold)\" opacity=\".3\"/>\r\n          <path d=\"M172 100 C145 90, 125 90, 100 100 C125 110, 145 110, 172 100 Z\" fill=\"url(#kgold)\" opacity=\".3\"/>\r\n          <path d=\"M49 49 C72 65, 86 78, 100 100 C78 86, 65 72, 49 49 Z\" fill=\"url(#kgold)\" opacity=\".3\"/>\r\n          <path d=\"M151 151 C128 135, 114 122, 100 100 C122 114, 135 128, 151 151 Z\" fill=\"url(#kgold)\" opacity=\".3\"/>\r\n          <path d=\"M151 49 C135 72, 122 86, 100 100 C114 78, 128 65, 151 49 Z\" fill=\"url(#kgold)\" opacity=\".3\"/>\r\n          <path d=\"M49 151 C65 128, 78 114, 100 100 C86 122, 72 135, 49 151 Z\" fill=\"url(#kgold)\" opacity=\".3\"/>\r\n        </g>\r\n      </svg>\r\n\r\n      <!-- 24K Gold Coin Medallion with Interlocking Royal Monogram -->\r\n      <div class=\"seal-medallion\" id=\"sealMedallion\" title=\"Click to open invitation\">\r\n        <span class=\"initials\" id=\"mono\">K❦M</span>\r\n        <span class=\"mini-ta\">ஸ்ரீ கணேசாய நமஹ</span>\r\n      </div>\r\n    </div>\r\n\r\n    <!-- Invitation Presentation Card -->\r\n    <div class=\"seal-card\">\r\n      <div class=\"eyebrow-seal\">✨ திருமண அழைப்பிதழ் • WEDDING INVITATION ✨</div>\r\n      <div class=\"names-seal\" id=\"gNames\">Karthik <span>&amp;</span> Meenakshi</div>\r\n      <div class=\"sub-seal\" id=\"gDetails\">Sunday, 14 February 2027<br>Sri Meenakshi Sundareswarar Kalyana Mandapam, Madurai</div>\r\n      <button class=\"btn-enter\" id=\"btnEnter\">\r\n        <span>✨ ENTER THE CELEBRATION</span>\r\n        <svg width=\"18\" height=\"18\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\" stroke-linecap=\"round\"><path d=\"m9 6 6 6-6 6\"/></svg>\r\n      </button>\r\n    </div>\r\n  </div>\r\n\r\n  <button class=\"skip\" id=\"skip\">Skip opening ✕</button>\r\n </div>\r\n</div>\r\n\r\n<!-- Real Bollywood Soundtrack: Mast Magan (2 States) -->\r\n<audio id=\"song\" src=\"/audio/mast-magan.mp3\" loop preload=\"auto\"></audio>\r\n\r\n<button id=\"music\" aria-label=\"Toggle wedding music\" title=\"Play soundtrack: Mast Magan (2 States)\">\r\n  <svg viewBox=\"0 0 24 24\" width=\"24\" height=\"24\" fill=\"none\" stroke=\"#f8efd6\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\">\r\n    <path d=\"M4 9v6h4l5 4V5L8 9z\" fill=\"#f8efd6\"/>\r\n    <g class=\"w\"><path d=\"M16 9a4 4 0 010 6\"/><path d=\"M18.5 6.5a8 8 0 010 11\"/></g>\r\n    <g class=\"x\"><path d=\"M16.5 9.5l4.5 5M21 9.5l-4.5 5\"/></g>\r\n  </svg>\r\n</button>\r\n\r\n<!-- ================= MAIN INVITATION APPLICATION CONTAINER ================= -->\r\n<main id=\"app\">\r\n\r\n<!-- ================= HERO : JASMINE THORANAM & ROYAL COUPLE ================= -->\r\n<section id=\"hero\" data-sec>\r\n <svg id=\"garland\" viewBox=\"0 0 1000 190\" preserveAspectRatio=\"xMidYMin slice\"></svg>\r\n <div class=\"hero-grid\">\r\n  <!-- Royal South Indian Couple in Ornate Brass Temple Prabhavali Arch -->\r\n  <div class=\"couple-arch-container rev\">\r\n    <div class=\"prabhavali-arch\">\r\n      <img src=\"/template-03/couple.jpg\" alt=\"Karthik &amp; Meenakshi\" class=\"couple-photo\" id=\"cPhoto\" />\r\n      <div class=\"arch-border-glow\"></div>\r\n      <div class=\"arch-crest\"><span class=\"crest-icon\">🪔</span></div>\r\n    </div>\r\n    <div class=\"couple-badge\">\r\n      <span id=\"fA\">Karthik</span>\r\n      <span class=\"badge-sep\">❦</span>\r\n      <span id=\"fB\">Meenakshi</span>\r\n    </div>\r\n  </div>\r\n\r\n  <!-- Center Luxury Invitation Namecard -->\r\n  <div class=\"namecard rev\">\r\n   <p class=\"ta\" style=\"color:var(--vermilion);font-size:1.15rem;margin:0 0 8px;font-weight:700\">திருமண அழைப்பிதழ்</p>\r\n   <p class=\"tiny\">WITH JOY &amp; SACRED BLESSINGS, WE INVITE YOU</p>\r\n   <h1 id=\"n1\">Karthik</h1>\r\n   <span class=\"amp\">&amp;</span>\r\n   <h1 id=\"n2\">Meenakshi</h1>\r\n   <p>Together with their families<br>request the honour of your presence at their wedding celebration</p>\r\n   <div class=\"pill\" id=\"dateTxt\">Sunday, 14 February 2027</div>\r\n   <p class=\"hero-venue\" id=\"hVenue\">Sri Meenakshi Sundareswarar Kalyana Mandapam, Madurai</p>\r\n  </div>\r\n </div>\r\n</section>\r\n\r\n<!-- ================= SAVE THE DATE ================= -->\r\n<section id=\"save\" data-sec>\r\n <p class=\"kick\" style=\"color:var(--gold)\">MARK YOUR CALENDAR</p>\r\n <h2 class=\"rev\">Save the date</h2><div class=\"dots\"><i></i></div><br>\r\n <div class=\"cal rev\"><h3 id=\"calM\">February 2027</h3><div class=\"g\" id=\"calG\"></div><p class=\"ft\" id=\"calF\">Sunday, 14 February</p></div>\r\n <p class=\"loc rev\" id=\"loc\">Sri Meenakshi Sundareswarar Kalyana Mandapam, Madurai</p>\r\n</section>\r\n\r\n<!-- ================= COUNTDOWN ================= -->\r\n<section id=\"count\" class=\"night pat\" data-sec>\r\n <p class=\"kick\">THE WAIT IS ALMOST OVER</p>\r\n <h2 class=\"rev\">Counting down to the big day</h2>\r\n <p class=\"sub rev\" id=\"cdDate\">Sunday, 14 February 2027</p>\r\n <div class=\"cd rev\">\r\n   <div class=\"tile\"><b id=\"d\">0</b><small>DAYS</small></div>\r\n   <div class=\"tile\"><b id=\"h\">0</b><small>HOURS</small></div>\r\n   <div class=\"tile\"><b id=\"mi\">0</b><small>MINUTES</small></div>\r\n   <div class=\"tile\"><b id=\"s\">0</b><small>SECONDS</small></div>\r\n </div>\r\n</section>\r\n\r\n<!-- ================= EVENTS TIMELINE ================= -->\r\n<section id=\"events\" data-sec>\r\n <p class=\"kick\">THE FESTIVITIES</p>\r\n <h2 class=\"rev\">The celebrations</h2><div class=\"dots\"><i></i></div>\r\n <p class=\"sub rev\">Four days of traditional Vedic rituals, Carnatic music, and joyous celebrations</p>\r\n <div class=\"tl\" id=\"tl\"></div>\r\n</section>\r\n\r\n<!-- ================= FAMILY & BLESSINGS ================= -->\r\n<section id=\"family\" class=\"pat\" data-sec>\r\n <p class=\"kick\" style=\"color:var(--gold)\">WITH LOVE FROM THE FAMILY</p>\r\n <h2 class=\"rev\">We can't wait to see you</h2>\r\n <p class=\"sub rev\">Reach out to us for anything you need</p>\r\n <div class=\"bar rev\"><small>WAITING TO WELCOME YOU</small><span id=\"fam\">Sundaram &amp; Kalyani Families</span></div>\r\n <div class=\"bar rev\"><small>FOR ANY HELP, CALL</small><span id=\"help\">Sundaram Iyer +91 94440 12345 · Ramanathan +91 94440 67890</span></div>\r\n <svg class=\"lights\" id=\"lights\" viewBox=\"0 0 1000 46\" preserveAspectRatio=\"none\"></svg>\r\n</section>\r\n\r\n<!-- ================= KUTHUVILAKKU TEMPLE LAMP ================= -->\r\n<section id=\"bless\" class=\"night pat\" data-sec>\r\n <p class=\"kick\">WITH THE BLESSINGS OF OUR ELDERS</p>\r\n <h2 class=\"rev\">Sri Ganeshaya Namaha</h2>\r\n <p class=\"sub rev\">Tap the sacred Kuthuvilakku brass lamp to light the flames and shower divine blessings</p>\r\n <button id=\"lantern\" aria-label=\"Light the sacred Kuthuvilakku temple lamp\">\r\n   <div class=\"halo\"></div>\r\n   <svg viewBox=\"0 0 240 330\">\r\n     <defs>\r\n       <linearGradient id=\"br\" x1=\"0\" x2=\"1\">\r\n         <stop offset=\"0\" stop-color=\"#6e4210\"/>\r\n         <stop offset=\".35\" stop-color=\"#e6b559\"/>\r\n         <stop offset=\".5\" stop-color=\"#fff0b0\"/>\r\n         <stop offset=\".7\" stop-color=\"#c58c2e\"/>\r\n         <stop offset=\"1\" stop-color=\"#6a3f0e\"/>\r\n       </linearGradient>\r\n     </defs>\r\n     <path d=\"M50 160C50 70 190 70 190 160\" fill=\"none\" stroke=\"url(#br)\" stroke-width=\"8\"/>\r\n     <g fill=\"#f4d77a\">\r\n       <circle cx=\"66\" cy=\"112\" r=\"3\"/><circle cx=\"84\" cy=\"94\" r=\"3\"/><circle cx=\"104\" cy=\"84\" r=\"3\"/>\r\n       <circle cx=\"136\" cy=\"84\" r=\"3\"/><circle cx=\"156\" cy=\"94\" r=\"3\"/><circle cx=\"174\" cy=\"112\" r=\"3\"/>\r\n     </g>\r\n     <circle cx=\"120\" cy=\"74\" r=\"8\" fill=\"url(#br)\"/>\r\n     <path d=\"M114 66h12l-6-14z\" fill=\"url(#br)\"/>\r\n     <!-- 5 Traditional Oil Lamp Wicks with Golden Glow -->\r\n     <rect x=\"53\" y=\"152\" width=\"6\" height=\"8\" fill=\"#6a3f0e\"/>\r\n     <g class=\"flame\"><path d=\"M56 152c-7-10-7-20 0-26 7 11 7 20 0 26z\" fill=\"#ffb12e\"/><path d=\"M56 150c-3-6-3-12 0-19 3 7 3 13 0 19z\" fill=\"#fff3b0\"/></g>\r\n     <rect x=\"85\" y=\"152\" width=\"6\" height=\"8\" fill=\"#6a3f0e\"/>\r\n     <g class=\"flame\"><path d=\"M88 152c-7-10-7-20 0-26 7 11 7 20 0 26z\" fill=\"#ffb12e\"/><path d=\"M88 150c-3-6-3-12 0-19 3 7 3 13 0 19z\" fill=\"#fff3b0\"/></g>\r\n     <rect x=\"117\" y=\"152\" width=\"6\" height=\"8\" fill=\"#6a3f0e\"/>\r\n     <g class=\"flame\"><path d=\"M120 152c-9-10-9-20 0-34 9 14 9 24 0 34z\" fill=\"#ffb12e\"/><path d=\"M120 150c-3-6-3-12 0-19 3 7 3 13 0 19z\" fill=\"#fff3b0\"/></g>\r\n     <rect x=\"149\" y=\"152\" width=\"6\" height=\"8\" fill=\"#6a3f0e\"/>\r\n     <g class=\"flame\"><path d=\"M152 152c-7-10-7-20 0-26 7 11 7 20 0 26z\" fill=\"#ffb12e\"/><path d=\"M152 150c-3-6-3-12 0-19 3 7 3 13 0 19z\" fill=\"#fff3b0\"/></g>\r\n     <rect x=\"181\" y=\"152\" width=\"6\" height=\"8\" fill=\"#6a3f0e\"/>\r\n     <g class=\"flame\"><path d=\"M184 152c-7-10-7-20 0-26 7 11 7 20 0 26z\" fill=\"#ffb12e\"/><path d=\"M184 150c-3-6-3-12 0-19 3 7 3 13 0 19z\" fill=\"#fff3b0\"/></g>\r\n     <path d=\"M42 160h156q-8 30-78 30T42 160z\" fill=\"url(#br)\"/>\r\n     <ellipse cx=\"120\" cy=\"160\" rx=\"78\" ry=\"9\" fill=\"#f4d77a\"/>\r\n     <ellipse cx=\"120\" cy=\"160\" rx=\"68\" ry=\"6\" fill=\"#ffd36b\" opacity=\".55\"/>\r\n     <rect x=\"110\" y=\"190\" width=\"20\" height=\"100\" fill=\"url(#br)\"/>\r\n     <ellipse cx=\"120\" cy=\"198\" rx=\"16\" ry=\"7\" fill=\"url(#br)\"/>\r\n     <ellipse cx=\"120\" cy=\"232\" rx=\"13\" ry=\"6\" fill=\"url(#br)\"/>\r\n     <ellipse cx=\"120\" cy=\"262\" rx=\"20\" ry=\"8\" fill=\"url(#br)\"/>\r\n     <path d=\"M78 296q42-14 84 0l-8-22q-34-8-68 0z\" fill=\"url(#br)\"/>\r\n     <path d=\"M50 318h140l-12-26H62z\" fill=\"url(#br)\"/>\r\n     <ellipse cx=\"120\" cy=\"318\" rx=\"70\" ry=\"6\" fill=\"#6a3f0e\"/>\r\n   </svg>\r\n </button>\r\n <p id=\"msg\" aria-live=\"polite\"></p>\r\n</section>\r\n\r\n<footer>\r\n <div class=\"fm\" id=\"fMono\">K❦M</div>\r\n <p class=\"fn\" id=\"fN\">KARTHIK &amp; MEENAKSHI</p>\r\n <div class=\"dots\"><i></i></div>\r\n <p class=\"big\">Your gracious presence and blessings mean everything to us.</p>\r\n <button class=\"btn ghost\" id=\"again\">Watch the invitation again</button>\r\n</footer>\r\n</main>\r\n\r\n<script>\r\nconst $ = id => document.getElementById(id);\r\n\r\n/* ===== CONFIGURATION: SOUTH INDIAN WEDDING DETAILS ===== */\r\nconst W = {\r\n  SHOW_PREVIEW_BAR: true,\r\n  n1: \"Karthik\", n2: \"Meenakshi\",\r\n  date: \"2027-02-14T09:00:00\",\r\n  venue: \"Sri Meenakshi Sundareswarar Kalyana Mandapam, Madurai\",\r\n  family: \"Sundaram & Kalyani / Ramanathan & Saraswathi Families\",\r\n  help: \"Sundaram Iyer +91 94440 12345 · Ramanathan +91 94440 67890\",\r\n  labelA: \"Karthik\", labelB: \"Meenakshi\",\r\n  song: {\r\n    title: \"Mast Magan\",\r\n    movie: \"2 States\",\r\n    artist: \"Arijit Singh, Chinmayi Sripada (T-Series)\",\r\n    source: \"/audio/mast-magan.mp3\"\r\n  },\r\n  events: [\r\n    { name: \"Nalangu\", d: 12, when: \"Friday, 12 February 2027\", time: \"10:00 AM\", where: \"Family ancestral home, Madurai\", note: \"Traditional turmeric paste, sandalwood fragrance, playful bridal games, and festive folk songs.\" },\r\n    { name: \"Jaanavasam\", d: 13, when: \"Saturday, 13 February 2027\", time: \"5:30 PM\", where: \"Sri Meenakshi Kalyana Mandapam, Madurai\", note: \"Grand baraat procession with live Nadaswaram, Carnatic music, and ceremonial garland exchange.\" },\r\n    { name: \"Muhurtham\", d: 14, when: \"Sunday, 14 February 2027\", time: \"9:00 AM\", where: \"Sri Meenakshi Kalyana Mandapam, Madurai\", note: \"Sacred Mangalya Dharanam (Thali tying), Saptapadi around agni, followed by royal banana-leaf Sadhya feast.\" },\r\n    { name: \"Reception\", d: 14, when: \"Sunday, 14 February 2027\", time: \"7:00 PM\", where: \"Hotel Heritage Grand Ballroom, Madurai\", note: \"Grand celebratory dinner, musical tributes, and blessings from friends and family.\" }\r\n  ]\r\n};\r\n\r\n/* ===== URL PARAMS & STUDIO SYNCHRONIZATION ===== */\r\nconst urlParams = new URLSearchParams(window.location.search);\r\nif (urlParams.get('bar') === 'false' || urlParams.get('mode') === 'demo') {\r\n  W.SHOW_PREVIEW_BAR = false;\r\n}\r\nif (urlParams.get('names')) {\r\n  const parts = urlParams.get('names').split(/&|\\band\\b/i).map(s => s.trim());\r\n  if (parts.length >= 2) {\r\n    W.n1 = parts[0];\r\n    W.n2 = parts[1];\r\n    W.labelA = parts[0];\r\n    W.labelB = parts[1];\r\n  }\r\n}\r\nif (urlParams.get('venue')) W.venue = urlParams.get('venue');\r\nif (urlParams.get('date')) W.date = urlParams.get('date');\r\n\r\ntry {\r\n  const stored = sessionStorage.getItem('ink_ivory_custom_template-03');\r\n  if (stored) {\r\n    const p = JSON.parse(stored);\r\n    if (p.names) {\r\n      const parts = p.names.split(/&|\\band\\b/i).map(s => s.trim());\r\n      if (parts.length >= 2) {\r\n        W.n1 = parts[0];\r\n        W.n2 = parts[1];\r\n        W.labelA = parts[0];\r\n        W.labelB = parts[1];\r\n      }\r\n    }\r\n    if (p.date) W.date = p.date;\r\n    if (p.venue) W.venue = p.venue;\r\n    if (p.host || p.family) W.family = p.host || p.family;\r\n    if (p.events && Array.isArray(p.events)) {\r\n      p.events.forEach((ev, i) => {\r\n        const dMatch = (ev.date || ev.when || '').match(/\\b([0-2]?[1-9]|10|20|30|31)\\b/);\r\n        const dayNum = dMatch ? dMatch[1] : (i === 0 ? 12 : i === 1 ? 13 : 14);\r\n        if (W.events[i]) {\r\n          if (ev.name) W.events[i].name = ev.name;\r\n          if (ev.date || ev.when) W.events[i].when = ev.date || ev.when;\r\n          if (ev.time) W.events[i].time = ev.time;\r\n          if (ev.venue || ev.where) W.events[i].where = ev.venue || ev.where;\r\n          if (ev.note) W.events[i].note = ev.note;\r\n          W.events[i].d = dayNum;\r\n        } else {\r\n          W.events.push({\r\n            name: ev.name || 'Ceremony',\r\n            d: dayNum,\r\n            when: ev.date || ev.when || W.date,\r\n            time: ev.time || '10:00 AM',\r\n            where: ev.venue || ev.where || W.venue,\r\n            note: ev.note || 'Sacred wedding festivities.'\r\n          });\r\n        }\r\n      });\r\n    }\r\n  }\r\n} catch(e) {}\r\n\r\n/* Hide bar if disabled */\r\nif (!W.SHOW_PREVIEW_BAR) {\r\n  document.body.classList.add('nobar');\r\n}\r\n\r\nconst D = new Date(W.date);\r\n\r\n/* Populate dynamic text */\r\nfunction populateData() {\r\n  const initials = `${W.n1.charAt(0)}❦${W.n2.charAt(0)}`;\r\n  if ($(\"mono\")) $(\"mono\").textContent = initials;\r\n  if ($(\"fMono\")) $(\"fMono\").textContent = initials;\r\n  if ($(\"lName\")) $(\"lName\").textContent = `${W.n1} & ${W.n2}`;\r\n  if ($(\"gNames\")) $(\"gNames\").innerHTML = `${W.n1} <span>&amp;</span> ${W.n2}`;\r\n  if ($(\"fN\")) $(\"fN\").textContent = `${W.n1.toUpperCase()} & ${W.n2.toUpperCase()}`;\r\n  if ($(\"n1\")) $(\"n1\").textContent = W.n1;\r\n  if ($(\"n2\")) $(\"n2\").textContent = W.n2;\r\n  if ($(\"fA\")) $(\"fA\").textContent = W.labelA;\r\n  if ($(\"fB\")) $(\"fB\").textContent = W.labelB;\r\n  if ($(\"loc\")) $(\"loc\").textContent = W.venue;\r\n  if ($(\"fam\")) $(\"fam\").textContent = W.family;\r\n  if ($(\"help\")) $(\"help\").textContent = W.help;\r\n  if ($(\"rNames\")) $(\"rNames\").innerHTML = `${W.n1} <span>&amp;</span> ${W.n2}`;\r\n  if ($(\"hVenue\")) $(\"hVenue\").textContent = W.venue;\r\n  if ($(\"gReveal\")) $(\"gReveal\").textContent = `Together with their families, cordially invite you to celebrate the sacred union of ${W.n1} & ${W.n2}`;\r\n\r\n  const dateOpts = { weekday: \"long\", day: \"numeric\", month: \"long\", year: \"numeric\" };\r\n  const dStr = D.toLocaleDateString(\"en-GB\", dateOpts);\r\n  if ($(\"dateTxt\")) $(\"dateTxt\").textContent = dStr;\r\n  if ($(\"cdDate\")) $(\"cdDate\").textContent = dStr;\r\n  if ($(\"gDetails\")) $(\"gDetails\").innerHTML = `${dStr}<br>${W.venue}`;\r\n}\r\npopulateData();\r\n\r\n/* ===== LOADER SCRIPT ===== */\r\n(function() {\r\n  const t0 = performance.now();\r\n  let s = `<circle cx=\"0\" cy=\"0\" r=\"48\"/><circle cx=\"0\" cy=\"0\" r=\"32\"/><circle cx=\"0\" cy=\"0\" r=\"14\"/>`;\r\n  for (let i = 0; i < 16; i++) {\r\n    const a = i * Math.PI / 8, x = Math.cos(a) * 48, y = Math.sin(a) * 48;\r\n    s += `<path d=\"M0 0 L${x} ${y}\" style=\"--d:${(i*.08).toFixed(2)}s\"/>`;\r\n    s += `<circle cx=\"${x}\" cy=\"${y}\" r=\"3\" fill=\"#d9a521\" style=\"--d:${(i*.08+.2).toFixed(2)}s\"/>`;\r\n  }\r\n  $(\"lm\").innerHTML = s;\r\n\r\n  function hideLoader() {\r\n    const l = $(\"loader\");\r\n    if (l) l.classList.add(\"hide\");\r\n  }\r\n  const isDemo = urlParams.get('mode') === 'demo' || urlParams.get('view') === 'phone';\r\n  if (isDemo || urlParams.get('skipOpening') === 'true') {\r\n    setTimeout(hideLoader, 200);\r\n  } else {\r\n    window.addEventListener(\"load\", () => {\r\n      setTimeout(hideLoader, Math.max(0, 1400 - (performance.now() - t0)));\r\n    });\r\n    setTimeout(hideLoader, 3000);\r\n  }\r\n  if ($(\"loader\")) {\r\n    $(\"loader\").onclick = hideLoader;\r\n    $(\"loader\").style.cursor = \"pointer\";\r\n  }\r\n})();\r\n\r\n/* ===== JASMINE + MARIGOLD DRAPING GARLAND ===== */\r\n(function() {\r\n  let s = `<rect width=\"1000\" height=\"9\" fill=\"#2d6e35\"/>`, col = [\"#fffaf0\", \"#fffaf0\", \"#f4a21e\", \"#fffaf0\", \"#c92a3e\"];\r\n  for (let x = 14, n = 0; x < 1000; x += 26, n++) {\r\n    s += `<path d=\"M${x-9} 6c-6 20-2 36 9 50c11-14 15-30 9-50z\" fill=\"${n%2?\"#2d6e35\":\"#1f5326\"}\"/>`;\r\n    const len = 64 + ((n * 37) % 94);\r\n    s += `<line x1=\"${x}\" y1=\"44\" x2=\"${x}\" y2=\"${len}\" stroke=\"#4a7032\" stroke-width=\"1.6\"/>`;\r\n    for (let y = 54, k = 0; y < len; y += 14, k++) {\r\n      const c = col[(n + k) % 5];\r\n      s += `<circle cx=\"${x}\" cy=\"${y}\" r=\"7\" fill=\"${c}\" stroke=\"#e8d9b0\" stroke-width=\".6\"/><circle cx=\"${x}\" cy=\"${y}\" r=\"2.4\" fill=\"${c===\"#fffaf0\"?\"#f4d77a\":\"#fff0c0\"}\"/>`;\r\n    }\r\n    s += `<circle cx=\"${x}\" cy=\"${len+6}\" r=\"5\" fill=\"#d9a521\"/>`;\r\n  }\r\n  $(\"garland\").innerHTML = s;\r\n})();\r\n\r\n/* ===== FESTIVE STRING LIGHTS ===== */\r\n(function() {\r\n  let s = \"\", c = [\"#f7de8a\", \"#c92a3e\", \"#fff\", \"#f5a623\"];\r\n  for (let x = 0; x <= 1000; x += 25) {\r\n    const y = 22 + Math.sin(x / 80) * 10;\r\n    s += `<circle cx=\"${x}\" cy=\"${y}\" r=\"4\" fill=\"${c[(x/25)%4|0]}\"/>`;\r\n  }\r\n  $(\"lights\").innerHTML = `<path d=\"M0 22 ${Array.from({length:41},(_,i)=>`L${i*25} ${22+Math.sin(i*25/80)*10}`).join(\" \")}\" stroke=\"#7a5a2a\" fill=\"none\"/>` + s;\r\n})();\r\n\r\n/* ===== DRIFTING JASMINE & MARIGOLD PETALS ON ENTRANCE GATE ===== */\r\n(function() {\r\n  const cv = $(\"gateCv\");\r\n  if (!cv) return;\r\n  const ctx = cv.getContext(\"2d\");\r\n  let w = cv.width = window.innerWidth;\r\n  let h = cv.height = window.innerHeight;\r\n  window.addEventListener(\"resize\", () => {\r\n    w = cv.width = window.innerWidth;\r\n    h = cv.height = window.innerHeight;\r\n  });\r\n\r\n  const petals = [];\r\n  const P_TYPES = [\"jasmine\", \"marigold\", \"spark\"];\r\n  for (let i = 0; i < 40; i++) {\r\n    petals.push({\r\n      x: Math.random() * w,\r\n      y: Math.random() * h,\r\n      size: 4 + Math.random() * 8,\r\n      speedY: 0.6 + Math.random() * 1.2,\r\n      speedX: (Math.random() - 0.5) * 0.8,\r\n      rot: Math.random() * 360,\r\n      rotSpeed: (Math.random() - 0.5) * 2,\r\n      type: P_TYPES[i % 3],\r\n      opacity: 0.4 + Math.random() * 0.5\r\n    });\r\n  }\r\n\r\n  function renderPetals() {\r\n    if ($(\"gate\").classList.contains(\"gone\")) return;\r\n    ctx.clearRect(0, 0, w, h);\r\n    for (let p of petals) {\r\n      p.y += p.speedY;\r\n      p.x += p.speedX + Math.sin(p.y * 0.015) * 0.5;\r\n      p.rot += p.rotSpeed;\r\n      if (p.y > h + 20) { p.y = -20; p.x = Math.random() * w; }\r\n\r\n      ctx.save();\r\n      ctx.translate(p.x, p.y);\r\n      ctx.rotate(p.rot * Math.PI / 180);\r\n      ctx.globalAlpha = p.opacity;\r\n\r\n      if (p.type === \"jasmine\") {\r\n        ctx.fillStyle = \"#fffaf0\";\r\n        ctx.beginPath();\r\n        ctx.ellipse(0, 0, p.size * 0.6, p.size, 0, 0, Math.PI * 2);\r\n        ctx.fill();\r\n        ctx.fillStyle = \"#f7de8a\";\r\n        ctx.beginPath();\r\n        ctx.arc(0, p.size * 0.5, p.size * 0.2, 0, Math.PI * 2);\r\n        ctx.fill();\r\n      } else if (p.type === \"marigold\") {\r\n        ctx.fillStyle = \"#f5a623\";\r\n        ctx.beginPath();\r\n        ctx.ellipse(0, 0, p.size * 0.8, p.size * 1.2, 0, 0, Math.PI * 2);\r\n        ctx.fill();\r\n      } else {\r\n        ctx.fillStyle = \"#f7de8a\";\r\n        ctx.shadowBlur = 6;\r\n        ctx.shadowColor = \"#f7de8a\";\r\n        ctx.beginPath();\r\n        ctx.arc(0, 0, p.size * 0.35, 0, Math.PI * 2);\r\n        ctx.fill();\r\n      }\r\n      ctx.restore();\r\n    }\r\n    requestAnimationFrame(renderPetals);\r\n  }\r\n  requestAnimationFrame(renderPetals);\r\n})();\r\n\r\n/* ===== CALENDAR BUILDER ===== */\r\nfunction buildCalendar() {\r\n  const y = D.getFullYear(), m = D.getMonth(), first = (new Date(y, m, 1).getDay() + 6) % 7, days = new Date(y, m + 1, 0).getDate();\r\n  let h = \"MTWTFSS\".split(\"\").map(l => `<span class=\"hd\">${l}</span>`).join(\"\");\r\n  for (let i = 0; i < first; i++) h += \"<span></span>\";\r\n  for (let d = 1; d <= days; d++) h += `<span class=\"${d === D.getDate() ? \"on\" : \"\"}\">${d}</span>`;\r\n  $(\"calG\").innerHTML = h;\r\n  $(\"calM\").textContent = D.toLocaleString(\"en\", { month: \"long\" }) + \" \" + y;\r\n  $(\"calF\").textContent = D.toLocaleDateString(\"en-GB\", { weekday: \"long\", day: \"numeric\", month: \"long\" });\r\n}\r\nbuildCalendar();\r\n\r\n/* ===== EVENTS TIMELINE WITH TEMPLE BELLS ===== */\r\nconst bell = `<svg viewBox=\"0 0 20 34\"><path d=\"M10 0v8\" stroke=\"#a87819\" stroke-width=\"1.5\"/><path d=\"M3 24c0-8 2-14 7-14s7 6 7 14z\" fill=\"#d9a521\"/><rect x=\"1\" y=\"24\" width=\"18\" height=\"3\" rx=\"1.5\" fill=\"#a87819\"/><circle cx=\"10\" cy=\"31\" r=\"2.6\" fill=\"#a87819\"/></svg>`;\r\nfunction buildEvents() {\r\n  $(\"tl\").innerHTML = W.events.map(e => `\r\n    <div class=\"row rev\">\r\n      <div class=\"card\">\r\n        <div class=\"bells\">${bell.repeat(4)}</div>\r\n        <h3>${e.name}</h3>\r\n        <p>${e.note}</p>\r\n        <p style=\"margin-top:6px;color:#0d382c\"><strong>${e.where}</strong></p>\r\n        <div class=\"acts\">\r\n          <a href=\"https://maps.google.com/?q=${encodeURIComponent(e.where)}\" target=\"_blank\" rel=\"noopener\">Directions</a>\r\n          <a href=\"https://maps.google.com/?q=${encodeURIComponent(e.where)}\" target=\"_blank\" rel=\"noopener\">Map</a>\r\n        </div>\r\n      </div>\r\n      <div class=\"dt\">${e.d}</div>\r\n      <div class=\"when\">${e.when}<small>${e.time}</small></div>\r\n    </div>\r\n  `).join(\"\");\r\n}\r\nbuildEvents();\r\n\r\n/* ===== COUNTDOWN TICKER ===== */\r\nfunction tick() {\r\n  const t = Math.max(0, D - Date.now());\r\n  $(\"d\").textContent = Math.floor(t / 864e5);\r\n  $(\"h\").textContent = Math.floor(t / 36e5 % 24);\r\n  $(\"mi\").textContent = Math.floor(t / 6e4 % 60);\r\n  $(\"s\").textContent = Math.floor(t / 1e3 % 60);\r\n}\r\ntick();\r\nsetInterval(tick, 1000);\r\n\r\nconst io = new IntersectionObserver(a => a.forEach(x => x.isIntersecting && x.target.classList.add(\"in\")), { threshold: .12 });\r\ndocument.querySelectorAll(\".rev\").forEach(e => io.observe(e));\r\n\r\n/* ===== REAL BOLLYWOOD SOUNDTRACK: MAST MAGAN (2 STATES) ===== */\r\nconst song = $(\"song\");\r\nif (song) {\r\n  if (urlParams.get('audioSource')) {\r\n    song.src = urlParams.get('audioSource');\r\n  }\r\n  const seekParam = urlParams.get('audioStart');\r\n  if (seekParam && !isNaN(seekParam)) {\r\n    song.currentTime = parseFloat(seekParam);\r\n  }\r\n}\r\nlet isPlaying = false;\r\n\r\nfunction toast(msg) {\r\n  const t = $(\"toast\");\r\n  if (!t) return;\r\n  t.textContent = msg;\r\n  t.classList.add(\"show\");\r\n  setTimeout(() => t.classList.remove(\"show\"), 3200);\r\n}\r\n\r\nfunction startMusic() {\r\n  if (isPlaying) return;\r\n  isPlaying = true;\r\n  $(\"music\").classList.add(\"on\");\r\n  if (song) {\r\n    song.volume = 0.75;\r\n    const playP = song.play();\r\n    if (playP !== undefined) {\r\n      playP.then(() => {\r\n        toast(\"🎶 Playing: Mast Magan (2 States)\");\r\n      }).catch(err => {\r\n        console.warn(\"Audio autoplay blocked by browser policy, will resume on user interaction\", err);\r\n      });\r\n    }\r\n  }\r\n}\r\n\r\nfunction stopMusic() {\r\n  isPlaying = false;\r\n  $(\"music\").classList.remove(\"on\");\r\n  if (song) {\r\n    song.pause();\r\n    toast(\"Music muted\");\r\n  }\r\n}\r\n\r\n$(\"music\").onclick = () => isPlaying ? stopMusic() : startMusic();\r\n\r\n/* Also unlock music on very first user interaction */\r\nfunction unlockAudioOnce() {\r\n  if (!isPlaying) {\r\n    startMusic();\r\n  }\r\n  document.removeEventListener('click', unlockAudioOnce);\r\n  document.removeEventListener('touchstart', unlockAudioOnce);\r\n}\r\ndocument.addEventListener('click', unlockAudioOnce, { once: true });\r\ndocument.addEventListener('touchstart', unlockAudioOnce, { once: true });\r\n\r\n/* ===== GATE OPENING LOGIC ===== */\r\nconst gate = $(\"gate\");\r\nfunction openGate(skip) {\r\n  if (gate.classList.contains(\"gone\")) return;\r\n  if (skip === true || gate.classList.contains(\"open\")) {\r\n    gate.classList.add(\"open\", \"gone\");\r\n    document.body.classList.remove(\"lock\");\r\n    document.body.classList.add(\"ready\");\r\n    if (isAutoPlaying) startAutoScroll();\r\n    return;\r\n  }\r\n  gate.classList.add(\"open\");\r\n  try { startMusic(); } catch(e) {}\r\n  setTimeout(() => {\r\n    gate.classList.add(\"gone\");\r\n    document.body.classList.remove(\"lock\");\r\n    document.body.classList.add(\"ready\");\r\n    if (isAutoPlaying) startAutoScroll();\r\n  }, 750);\r\n}\r\n\r\n$(\"btnEnter\").onclick = e => { e.stopPropagation(); openGate(); };\r\n$(\"sealMedallion\").onclick = e => { e.stopPropagation(); openGate(); };\r\ngate.onclick = () => openGate();\r\ngate.addEventListener(\"touchstart\", () => openGate(), { passive: true });\r\ngate.onkeydown = e => (e.key === \"Enter\" || e.key === \" \") && openGate();\r\n$(\"skip\").onclick = e => { e.stopPropagation(); openGate(true); };\r\n\r\nif (urlParams.get('skipOpening') === 'true') {\r\n  openGate(true);\r\n}\r\n$(\"again\").onclick = () => {\r\n  gate.classList.remove(\"open\", \"gone\");\r\n  document.body.classList.add(\"lock\");\r\n  document.body.classList.remove(\"ready\");\r\n  scrollTo(0, 0);\r\n};\r\n\r\n/* ===== KUTHUVILAKKU TEMPLE LAMP LIGHTING ===== */\r\n$(\"lantern\").onclick = () => {\r\n  $(\"lantern\").classList.add(\"lit\");\r\n  for (let i = 0; i < 28; i++) {\r\n    const s = document.createElement(\"i\");\r\n    s.className = \"star\";\r\n    const a = Math.random() * 6.28, r = 70 + Math.random() * 100;\r\n    s.style.setProperty(\"--x\", Math.cos(a) * r + \"px\");\r\n    s.style.setProperty(\"--y\", Math.sin(a) * r + \"px\");\r\n    $(\"lantern\").appendChild(s);\r\n    setTimeout(() => s.remove(), 2500);\r\n  }\r\n  $(\"msg\").textContent = \"✨ The auspicious Kuthuvilakku is lit! Divine blessings showered upon the couple.\";\r\n};\r\n\r\n/* ===== PREVIEW BAR NAVIGATION ===== */\r\nconst SECS = () => Array.from(document.querySelectorAll('section[data-sec]'));\r\nfunction curIndex() {\r\n  const y = scrollY + innerHeight * .35;\r\n  let idx = 0;\r\n  SECS().forEach((s, i) => { if (s.offsetTop <= y) idx = i; });\r\n  return idx;\r\n}\r\nfunction goto(i) {\r\n  const secs = SECS();\r\n  if (!secs.length) return;\r\n  const target = secs[Math.max(0, Math.min(secs.length - 1, i))];\r\n  target.scrollIntoView({ behavior: 'smooth', block: 'start' });\r\n}\r\n\r\n$(\"bPrev\").onclick = () => goto(curIndex() - 1);\r\n$(\"bNext\").onclick = () => goto(curIndex() + 1);\r\n$(\"bBack\").onclick = () => { if (history.length > 1) history.back(); else goto(0); };\r\n\r\n/* ===== PHONE AUTO-SCROLL (Completely Disabled - User Manual Scroll Only) ===== */\r\nlet autoScrollTimer = null;\r\nlet isAutoPlaying = false;\r\n\r\nfunction startAutoScroll() {\r\n  // Disabled: No auto-scroll, card is manually scrolled by user\r\n  return;\r\n}\r\n\r\nfunction stopAutoScroll() {\r\n  if (autoScrollTimer) clearInterval(autoScrollTimer);\r\n  autoScrollTimer = null;\r\n}\r\n\r\n/* ===== STUDIO IFRAME MESSAGING ===== */\r\nwindow.addEventListener('message', (e) => {\r\n  if (!e.data) return;\r\n  if (e.data.action === 'prevSlide') {\r\n    goto(curIndex() - 1);\r\n  } else if (e.data.action === 'nextSlide') {\r\n    goto(curIndex() + 1);\r\n  } else if (e.data.action === 'toggleAutoPlay') {\r\n    isAutoPlaying = !isAutoPlaying;\r\n    if (isAutoPlaying) startAutoScroll(); else stopAutoScroll();\r\n  } else if (e.data.type === 'INK_IVORY_CUSTOM_UPDATE') {\r\n    const p = e.data.payload || {};\r\n    if (p.names) {\r\n      const parts = p.names.split(/&|\\band\\b/i).map(s => s.trim());\r\n      if (parts.length >= 2) {\r\n        W.n1 = parts[0];\r\n        W.n2 = parts[1];\r\n        W.labelA = parts[0];\r\n        W.labelB = parts[1];\r\n      } else {\r\n        W.n1 = p.names;\r\n      }\r\n    }\r\n    if (p.venue) W.venue = p.venue;\r\n    if (p.date) {\r\n      W.date = p.date;\r\n      const parsedD = new Date(p.date);\r\n      if (!isNaN(parsedD.getTime())) {\r\n        D.setTime(parsedD.getTime());\r\n      }\r\n      buildCalendar();\r\n    }\r\n    if (p.venue) W.venue = p.venue;\r\n    if (p.host || p.family) W.family = p.host || p.family;\r\n    if (p.events && Array.isArray(p.events)) {\r\n      p.events.forEach((ev, i) => {\r\n        const dMatch = (ev.date || ev.when || '').match(/\\b([0-2]?[1-9]|10|20|30|31)\\b/);\r\n        const dayNum = dMatch ? dMatch[1] : (i === 0 ? 12 : i === 1 ? 13 : 14);\r\n        if (W.events[i]) {\r\n          if (ev.name) W.events[i].name = ev.name;\r\n          if (ev.date || ev.when) W.events[i].when = ev.date || ev.when;\r\n          if (ev.time) W.events[i].time = ev.time;\r\n          if (ev.venue || ev.where) W.events[i].where = ev.venue || ev.where;\r\n          if (ev.note) W.events[i].note = ev.note;\r\n          W.events[i].d = dayNum;\r\n        } else {\r\n          W.events.push({\r\n            name: ev.name || 'Ceremony',\r\n            d: dayNum,\r\n            when: ev.date || ev.when || W.date,\r\n            time: ev.time || '10:00 AM',\r\n            where: ev.venue || ev.where || W.venue,\r\n            note: ev.note || 'Sacred wedding festivities.'\r\n          });\r\n        }\r\n      });\r\n      buildEvents();\r\n    }\r\n    populateData();\r\n    if (p.audioStartTime !== undefined && song) {\r\n      song.currentTime = parseFloat(p.audioStartTime);\r\n    }\r\n    if (p.audioSource && song && !song.src.endsWith(p.audioSource)) {\r\n      song.src = p.audioSource;\r\n      song.load();\r\n      if (p.audioStartTime !== undefined) {\r\n        song.currentTime = parseFloat(p.audioStartTime);\r\n      }\r\n      try { song.play(); } catch(err) {}\r\n    }\r\n  }\r\n});\r\n</script>\r\n</body>\r\n</html>";
